pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address proposedAddress, string memory typeStr, uint256 oldProposalID, uint256 newProposalID) public {
        // Ensure coolOffPeriod is set to 1 (default in init) for the test
        // We need to call init first
        c.init(address(0x1), address(0x2), address(0x3));

        // Create a new proposal to have a proposalCount > 0
        vm.assume(bytes(typeStr).length > 0);
        vm.assume(proposedAddress != address(0));

        // Create first proposal
        c.newAddressProposal(proposedAddress, typeStr);
        uint256 countAfterFirst = c.proposalCount();

        // Create second proposal
        c.newAddressProposal(proposedAddress, typeStr);
        uint256 countAfterSecond = c.proposalCount();

        // Now try to cancel with these IDs (they may or may not be valid, but we can still check the invariant)
        // Bound oldProposalID and newProposalID to be within the range of existing proposals
        vm.assume(oldProposalID >= 1 && oldProposalID <= countAfterSecond);
        vm.assume(newProposalID >= 1 && newProposalID <= countAfterSecond);
        vm.assume(oldProposalID != newProposalID);

        // Attempt cancel - it may revert, but we only care about the effect on proposalCount if it succeeds
        // We'll call it and catch revert
        uint256 countBeforeCancel = c.proposalCount();
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancelProposal(uint256,uint256)", oldProposalID, newProposalID));
        uint256 countAfterCancel = c.proposalCount();

        // The general rule: proposalCount should never decrease after any sequence of operations
        // So countAfterCancel should be >= countBeforeCancel
        assertTrue(countAfterCancel >= countBeforeCancel, "proposalCount decreased");
    }
}

