pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oldProposalID, uint256 newProposalID, address recipient, uint256 amount, address voter) public {
        vm.assume(oldProposalID > 0 && newProposalID > 0);
        vm.assume(oldProposalID != newProposalID);
        vm.assume(recipient != address(0));
        vm.assume(voter != address(0));
        vm.assume(amount > 0);

        // Create two proposals using newGrantProposal (which adds 2 to proposalCount per call)
        vm.startPrank(voter);
        c.newGrantProposal(recipient, amount);
        c.newGrantProposal(recipient, amount);
        vm.stopPrank();

        uint256 proposalCountBefore = c.proposalCount();

        // We need oldProposalID and newProposalID to be valid and different
        // The last created proposal has ID = proposalCountBefore
        // The second-to-last has ID = proposalCountBefore - 2
        vm.assume(oldProposalID <= proposalCountBefore);
        vm.assume(newProposalID <= proposalCountBefore);
        vm.assume(oldProposalID % 2 == 0); // even IDs from newGrantProposal
        vm.assume(newProposalID % 2 == 0); // even IDs from newGrantProposal

        // Ensure the old proposal is finalising (needed for cancelProposal to not revert)
        // We can't easily make it finalising without going through vote logic, so we use vm.assume to filter
        vm.assume(c.mapPID_finalising(oldProposalID) == true);

        // Ensure newProposal has minority
        vm.assume(c.hasMinority(newProposalID) == true);

        // Ensure same type (both are "GRANT")

        // Execute cancelProposal
        vm.prank(voter);
        c.cancelProposal(oldProposalID, newProposalID);

        // Check that proposalCount remains unchanged (should be same as before)
        assertTrue(c.proposalCount() == proposalCountBefore, "proposalCount should not change after cancelProposal");
    }
}

