pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oldProposalID, uint256 newProposalID) public {
        // Ensure valid IDs: cancelProposal requires finalising and different IDs
        vm.assume(oldProposalID > 0 && newProposalID > 0);
        vm.assume(oldProposalID != newProposalID);

        // Create proposals to ensure the IDs are realistic
        vm.assume(oldProposalID <= 1000 && newProposalID <= 1000);

        // Simulate creating proposals up to the max ID
        for (uint256 i = 0; i < 1000; i++) {
            c.newGrantProposal(address(uint160(i + 1)), 1000);
        }

        // Now call cancelProposal
        // Note: This will revert if conditions not met; we wrap in try/catch
        try c.cancelProposal(oldProposalID, newProposalID) {
            // After cancelProposal, proposalCount should be consistent
            uint256 propCount = c.proposalCount();
            // In reference, each newGrantProposal increments exactly once, so after N calls, proposalCount = N
            // In buggy version, it increments twice, so proposalCount = 2*N
            // After cancelProposal, the count should still reflect the number of calls
            // Since we made exactly 1000 calls, proposalCount should be 1000 in reference
            assertTrue(propCount == 1000);
        } catch {
            // If it reverts, the rule is vacuously true
            assertTrue(true);
        }
    }
}

