contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _vader, address _usdv, address _vault, address recipient, uint amount, uint oldProposalID, uint newProposalID) public {
        // bound inputs to avoid overflow/underflow issues
        vm.assume(_vader != address(0) && _usdv != address(0) && _vault != address(0));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0 && amount <= 1e30);

        // Initialize
        c.init(_vader, _usdv, _vault);

        // Record USDV before cancelProposal
        address usdvBefore = c.USDV();

        // Create proposals that might be needed for cancelProposal
        // We create two grant proposals to have something to reference
        c.newGrantProposal(recipient, amount);
        c.newGrantProposal(recipient, amount);

        // Try to call cancelProposal - it may revert, but we just need the state after
        // We'll set oldProposalID and newProposalID to valid values (1 and 2)
        vm.assume(oldProposalID == 1 && newProposalID == 2);

        // Call cancelProposal - it will likely revert due to requirements, but that's fine
        // The state change we care about is USDV, which is never modified by cancelProposal
